"use strict";
(()=>{const L=window.Lab;if(!L||!L.$('fourier-transform-lab'))return;L.init(['width','amplitude'],()=>{const T=L.range('width'),A=L.range('amplitude'),X=w=>Math.abs(w)<1e-10?A*T:A*T*Math.sin(w*T/2)/(w*T/2),g=L.$('drawing');g.replaceChildren();const a=L.svg('g'),b=L.svg('g',{transform:'translate(0,270)'});g.append(a,b);L.plot(a,[{points:[[-2,0],[-T/2,0],[-T/2,A],[T/2,A],[T/2,0],[2,0]],color:'#172a45'}],{xMin:-2,xMax:2,yMin:0,yMax:2.2,height:260,xLabel:'時間 t（s）；固定 −2 到 2 s',yLabel:'脈衝電壓 x（V）'});L.plot(b,[{fn:X}],{xMin:-8*Math.PI,xMax:8*Math.PI,yMin:-1,yMax:4.2,height:270,xLabel:'角頻率 ω（rad/s）',yLabel:'帶正負的 X（V·s），不是 |X|'});L.text('result-primary',L.fmt(A*T)+' V·s');L.text('result-secondary','±'+L.fmt(2*Math.PI/T)+' rad/s');L.text('feedback','X(0) 是面積 A×T = '+L.fmt(A*T)+' V·s；第一零點在 ±2π/T = ±'+L.fmt(2*Math.PI/T)+' rad/s（±'+L.fmt(1/T)+' Hz）。固定高度縮窄脈衝，面積會減少而主瓣變寬；圖的時間與頻率尺度保持固定。頻譜旁瓣可為負，是相消後的帶符號轉換值。');});})();
